WITH gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at ASC, id ASC) > INTERVAL '14' DAY THEN 1 ELSE 0 END AS session_start_flag FROM payments), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY order_id ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT CASE WHEN session_start_flag >= 1 THEN 'HIGH' ELSE 'LOW' END AS session_start_flag_tier, MIN(paid_at) AS started_at, COUNT(CASE WHEN status = 'FAILED' THEN 1 END) AS failed_count, MIN(paid_at) AS first_seen, COUNT_IF(status = 'REFUNDED') AS refunded_events, PERCENTILE_APPROX(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles, COUNT(*) AS event_count FROM islands GROUP BY CASE WHEN session_start_flag >= 1 THEN 'HIGH' ELSE 'LOW' END ORDER BY event_count ASC NULLS LAST
